select case when balance >= 78000 then 'high' when balance >= 35000 then 'mid' else 'low' end balance_bucket, case when status in ('FROZEN', 'CLOSED') then 'group_a' else 'other' end status_group, status, sum(case when account_type = 'CREDIT' then balance else 0 end) credit_balance, max(opened_date) latest_opened_date, sort_array(collect_set(account_type)) account_type_list from accounts where balance > 49000 group by 1, 2, 3 order by latest_opened_date, balance_bucket, status_group, status limit 1
